problems.solution:
def fibonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

tests.src:
def ref(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

for n in range(15):
    assert fibonacci(n) == ref(n), (n, fibonacci(n), ref(n))

