def is_palindrome(s):
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return is_palindrome(s[1:-1])

def power(base, exponent):
    if exponent == 0:
        return 1
    return base * power(base, exponent - 1)

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def digit_sum(n):
    if n == 0:
        return 0
    return n % 10 + digit_sum(n // 10)

