problems.solution:
def binary_search(values, target):

    def search(low, high):
        if low > high:
            return -1
        mid = (low + high) // 2
        if values[mid] == target:
            return mid
        if values[mid] < target:
            return search(mid + 1, high)
        return search(low, mid - 1)

    return search(0, len(values) - 1)

